//! A deterministic random editing session, used by the benchmarks, the crash-test writer and the
//! property tests. The same seed always produces the same sequence of commands, so a log written
//! by one process can be regenerated by another.

use crate::engine::Workspace;
use crate::error::{Error, Result};
use crate::exec::Rng;
use crate::ids::{ObjectId, OpId};
use crate::value::Value;

#[derive(Clone, Debug)]
pub struct ScriptOptions {
    /// Include undo / redo / branch switching among the steps.
    pub navigate: bool,
    /// Size of the synthetic geometry attached to each created box (bytes).
    pub geom_bytes: usize,
    /// Never create more than this many objects (edits dominate afterwards).
    pub max_objects: usize,
    /// Share of steps (per mille) that are navigation when `navigate` is on.
    pub nav_permille: u64,
}

impl Default for ScriptOptions {
    fn default() -> Self {
        ScriptOptions { navigate: true, geom_bytes: 256, max_objects: 100_000, nav_permille: 70 }
    }
}

pub struct Script {
    rng: Rng,
    pub opts: ScriptOptions,
    known: Vec<ObjectId>,
    branches: u32,
    pub steps: u64,
}

/// What one step did.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Step {
    Op(OpId),
    Undo,
    Redo,
    Branch,
    Switch,
    /// The chosen command was rejected (stale object after navigation); nothing was committed.
    Skipped,
}

fn f3(rng: &mut Rng, scale: f64) -> Value {
    Value::f3([rng.next_f64() * scale, rng.next_f64() * scale, rng.next_f64() * scale])
}

impl Script {
    pub fn new(seed: u64, opts: ScriptOptions) -> Script {
        Script { rng: Rng::new(seed), opts, known: Vec::new(), branches: 0, steps: 0 }
    }

    /// Start editing objects that already exist (for example ones received from another session).
    pub fn adopt(&mut self, ids: impl IntoIterator<Item = ObjectId>) {
        self.known.extend(ids);
    }

    fn pick(&mut self) -> Option<ObjectId> {
        if self.known.is_empty() {
            None
        } else {
            let i = self.rng.below(self.known.len() as u64) as usize;
            Some(self.known[i])
        }
    }

    fn forget(&mut self, id: ObjectId) {
        if let Some(i) = self.known.iter().position(|k| *k == id) {
            self.known.swap_remove(i);
        }
    }

    /// Perform one randomly chosen step against `ws`.
    pub fn step(&mut self, ws: &mut Workspace) -> Result<Step> {
        self.steps += 1;
        let roll = self.rng.below(1000);
        if self.opts.navigate && roll < self.opts.nav_permille {
            return match self.rng.below(70) {
                0..=29 => Ok(ws.undo()?.map_or(Step::Skipped, |_| Step::Undo)),
                30..=54 => Ok(ws.redo()?.map_or(Step::Skipped, |_| Step::Redo)),
                55..=59 => {
                    self.branches += 1;
                    ws.branch(&format!("option-{}", self.branches))?;
                    Ok(Step::Branch)
                }
                _ => {
                    let names: Vec<String> = ws.branches().map(|(n, _)| n.clone()).collect();
                    if names.is_empty() {
                        return Ok(Step::Skipped);
                    }
                    let n = &names[self.rng.below(names.len() as u64) as usize];
                    ws.switch(n)?;
                    Ok(Step::Switch)
                }
            };
        }
        let mut used: Option<ObjectId> = None;
        let want_create = self.known.len() < self.opts.max_objects && (self.known.len() < 8 || roll % 8 == 0);
        let (cmd, params, created): (&str, Value, Vec<ObjectId>) = if want_create || self.known.is_empty() {
            let (actor, seq) = ws.next_dot();
            let id = ObjectId::derive(actor, seq, 0);
            let n = self.steps;
            let params = Value::map([
                ("name", Value::Str(format!("box{n}"))),
                ("pos", f3(&mut self.rng, 100.0)),
                ("size", f3(&mut self.rng, 5.0)),
                ("layer", Value::Str(format!("L{}", self.rng.below(8)))),
                ("color", Value::Int(self.rng.below(256) as i64)),
                ("geom_bytes", Value::Int(self.opts.geom_bytes as i64)),
                ("tags", Value::List(vec![Value::str("new")])),
            ]);
            ("create_box", params, vec![id])
        } else {
            let Some(id) = self.pick() else { return Ok(Step::Skipped) };
            used = Some(id);
            let kind = self.rng.below(100);
            match kind {
                0..=44 => ("move", Value::map([("ids", Value::List(vec![Value::Obj(id)])), ("delta", f3(&mut self.rng, 2.0))]), vec![]),
                45..=59 => {
                    let prop = ["color", "layer", "name"][self.rng.below(3) as usize];
                    let value = match prop {
                        "color" => Value::Int(self.rng.below(256) as i64),
                        "layer" => Value::Str(format!("L{}", self.rng.below(8))),
                        _ => Value::Str(format!("n{}", self.rng.below(1000))),
                    };
                    ("set_prop", Value::map([("id", Value::Obj(id)), ("prop", Value::str(prop)), ("value", value)]), vec![])
                }
                60..=67 => ("tag_add", Value::map([("id", Value::Obj(id)), ("tag", Value::Str(format!("t{}", self.rng.below(6))))]), vec![]),
                68..=72 => ("tag_remove", Value::map([("id", Value::Obj(id)), ("tag", Value::Str(format!("t{}", self.rng.below(6))))]), vec![]),
                73..=82 => ("pts_insert", Value::map([("id", Value::Obj(id)), ("index", Value::Int(self.rng.below(5) as i64)), ("point", f3(&mut self.rng, 10.0))]), vec![]),
                83..=86 => ("pts_move", Value::map([("id", Value::Obj(id)), ("index", Value::Int(self.rng.below(3) as i64)), ("point", f3(&mut self.rng, 10.0))]), vec![]),
                87..=89 => ("pts_delete", Value::map([("id", Value::Obj(id)), ("index", Value::Int(self.rng.below(3) as i64))]), vec![]),
                90..=92 => ("delete", Value::map([("ids", Value::List(vec![Value::Obj(id)]))]), vec![]),
                93..=94 => ("keep", Value::map([("ids", Value::List(vec![Value::Obj(id)]))]), vec![]),
                95..=97 => {
                    let (actor, seq) = ws.next_dot();
                    let n = 1 + self.rng.below(3) as usize;
                    let ids = (0..n).map(|k| ObjectId::derive(actor, seq, k as u32)).collect();
                    ("array", Value::map([("src", Value::Obj(id)), ("n", Value::Int(n as i64)), ("delta", f3(&mut self.rng, 3.0))]), ids)
                }
                _ => {
                    let (actor, seq) = ws.next_dot();
                    let n = 1 + self.rng.below(4) as usize;
                    let ids = (0..n).map(|k| ObjectId::derive(actor, seq, k as u32)).collect();
                    ("scatter", Value::map([("count", Value::Int(n as i64)), ("extent", Value::Float(50.0)), ("layer", Value::str("S"))]), ids)
                }
            }
        };
        match ws.run(cmd, params) {
            Ok(op) => {
                self.known.extend(created);
                Ok(Step::Op(op))
            }
            Err(Error::Command(m)) => {
                // stale reference after navigation or deletion: drop it and carry on
                if let Some(id) = used {
                    if m.contains("no such object") || m.contains("deleted") {
                        self.forget(id);
                    }
                }
                Ok(Step::Skipped)
            }
            Err(e) => Err(e),
        }
    }
}
